//! csv and xlsx parsers, the zip guard and file-level sniffing against the
//! synthetic fixtures in `testing/super-ontology/fixtures/files` (generated by
//! `gen_files.py`), plus the golden-label anchor check (B-S3-02, B-S3-03).

use std::collections::BTreeSet;
use std::fs;
use std::io::Cursor;
use std::path::{Path, PathBuf};

use oo_core::docir::{Anchor, Block, BlockFlag, BlockKind, a1_parse};
use oo_docs::ingest::sniff::{Format, Verdict, sniff_reader};
use oo_docs::ingest::zipguard;
use oo_docs::normalize::Normalized;
use oo_docs::parse::ParseError;
use oo_docs::parse::csv::{parse_csv, parse_csv_fragment_capped, sniff_delimiter};
use oo_docs::parse::xlsx::{parse_xlsx, parse_xlsx_fragment_capped};

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../testing/super-ontology")
}

fn fixture(name: &str) -> Vec<u8> {
    fs::read(root().join("fixtures/files").join(name)).unwrap()
}

fn xlsx(name: &str) -> Normalized {
    parse_xlsx(&fixture(name)).unwrap()
}

fn csv(name: &str) -> Normalized {
    parse_csv(&fixture(name)).unwrap()
}

fn cells_range(b: &Block) -> (Option<&str>, &str) {
    match &b.anchor {
        Anchor::Cells { sheet, range } => (sheet.as_deref(), range.as_str()),
        other => panic!("not a cells anchor: {other:?}"),
    }
}

fn by_range<'a>(n: &'a Normalized, range: &str) -> &'a Block {
    n.ir.blocks
        .iter()
        .find(|b| cells_range(b).1 == range)
        .unwrap_or_else(|| panic!("no block at {range}"))
}

// ---- xlsx -----------------------------------------------------------------

#[test]
fn parse_xlsx_regions_header_kv_and_merged_cells() {
    let n = xlsx("xlsx-merged-regions.xlsx");
    assert_eq!(n.ir.meta.sheets, vec!["预算 2026".to_owned()]);

    // A lone cell above the table is a paragraph.
    let title = by_range(&n, "A1");
    assert_eq!(title.kind, BlockKind::Paragraph);
    assert_eq!(title.text, "2026 预算");
    assert_eq!(title.hpath, vec!["预算 2026".to_owned()]);

    // Region 1: rows 3..7, header row 3, columns A..D.
    let table = by_range(&n, "A3:D7");
    assert_eq!(table.kind, BlockKind::SheetTable);
    let grid = table.table.as_ref().unwrap();
    assert_eq!((grid.rows, grid.cols, grid.header_rows), (5, 4, 1));
    assert!(table.flags.contains(&BlockFlag::MergedCellsExpanded));
    assert!(table.flags.contains(&BlockFlag::FormulaCached));
    assert!(table.flags.contains(&BlockFlag::FormulaNoCache));
    assert!(!table.flags.contains(&BlockFlag::HeaderInferred));
    // Merged B4:B5: both cells carry the value and the region size (rs=2).
    let b4 = grid.cells.iter().find(|c| (c.r, c.c) == (1, 1)).unwrap();
    let b5 = grid.cells.iter().find(|c| (c.r, c.c) == (2, 1)).unwrap();
    assert_eq!((b4.text.as_str(), b4.rs, b4.cs), ("研发", Some(2), None));
    assert_eq!((b5.text.as_str(), b5.rs, b5.cs), ("研发", Some(2), None));
    assert!(
        grid.cells
            .iter()
            .filter(|c| c.r == 0)
            .all(|c| c.header == Some(true))
    );

    // Row blocks: header -> value lines, A1 range over the region's columns.
    let r4 = by_range(&n, "A4:D4");
    assert_eq!(r4.kind, BlockKind::Kv);
    assert_eq!(r4.parent.as_deref(), Some(table.id.as_str()));
    assert_eq!(
        r4.text,
        "姓名: 林远舟\n部门: 研发\n金额: 1200\n入职日期: 2026-03-01"
    );
    let r5 = by_range(&n, "A5:D5");
    assert_eq!(
        r5.text,
        "姓名: 周若溪\n部门: 研发\n金额: 980.5\n入职日期: 2026-03-19T18:00:00"
    );
    assert!(r5.flags.contains(&BlockFlag::MergedCellsExpanded));
    let r6 = by_range(&n, "A6:D6");
    assert!(r6.text.contains("金额: 2180.5"));
    assert_eq!(r6.flags, vec![BlockFlag::FormulaCached]);
    // A formula without a cached value is flagged and has no value text.
    let r7 = by_range(&n, "A7:D7");
    assert_eq!(r7.text, "姓名: 待算");
    assert_eq!(r7.flags, vec![BlockFlag::FormulaNoCache]);

    // Region 2 after a blank row: its own table, typed cells.
    let t2 = by_range(&n, "A9:B10");
    assert_eq!(t2.kind, BlockKind::SheetTable);
    assert_eq!(by_range(&n, "A10:B10").text, "编号: 101\n状态: TRUE");
}

#[test]
fn parse_xlsx_is_deterministic_and_fragment_forms_hold() {
    let a = xlsx("xlsx-merged-regions.xlsx");
    let b = xlsx("xlsx-merged-regions.xlsx");
    assert_eq!(a.ir_b3, b.ir_b3);
    assert_eq!(a.canonical, b.canonical);
    let frags: Vec<String> = a.ir.blocks.iter().map(|b| b.anchor.fragment()).collect();
    // Sheet names with a space are single-quoted in provenance fragments.
    assert!(
        frags.contains(&"#'预算 2026'!A4:D4".to_owned()),
        "{frags:?}"
    );
}

#[test]
fn parse_xlsx_skips_hidden_sheets_with_a_warning() {
    let n = xlsx("xlsx-hidden-sheet.xlsx");
    assert_eq!(n.ir.meta.sheets, vec!["公开".to_owned()]);
    assert!(n.ir.blocks.iter().all(|b| !b.text.contains("secret")));
    assert!(
        n.ir.warnings
            .iter()
            .any(|w| w.code == "DOCS_PARSE_HIDDEN_SKIPPED")
    );
}

#[test]
fn parse_xlsx_sparse_sheet_does_not_allocate_its_bounding_box() {
    // Cells at A1 and XFD1048576: a dense range would be 17 billion cells.
    let n = xlsx("xlsx-sparse-corners.xlsx");
    assert_eq!(n.ir.blocks.len(), 2);
    assert!(n.ir.blocks.iter().all(|b| b.kind == BlockKind::Paragraph));
    assert_eq!(cells_range(&n.ir.blocks[1]).1, "XFD1048576");
}

#[test]
fn parse_xlsx_macros_and_empty() {
    assert_eq!(xlsx("xlsx-macros.xlsx").ir.meta.has_macros, Some(true));
    assert_eq!(xlsx("xlsx-merged-regions.xlsx").ir.meta.has_macros, None);
    let e = xlsx("xlsx-empty.xlsx");
    assert!(e.ir.blocks.is_empty());
    assert!(e.ir.warnings.iter().any(|w| w.code == "DOCS_PARSE_EMPTY"));
}

#[test]
fn parse_xlsx_cell_cap() {
    let bytes = fixture("xlsx-merged-regions.xlsx");
    assert!(parse_xlsx_fragment_capped(&bytes, 100).is_ok());
    assert_eq!(
        parse_xlsx_fragment_capped(&bytes, 5).unwrap_err(),
        ParseError::LimitCells
    );
    // Merge expansion counts toward the cap too (B4:B5 adds one cell).
    let exact = parse_xlsx_fragment_capped(&bytes, 100).unwrap();
    // Grid cells of both tables plus the title paragraph.
    let cells: usize = 1 + exact
        .blocks
        .iter()
        .filter(|b| b.kind == BlockKind::SheetTable)
        .map(|b| b.table.as_ref().unwrap().cells.len())
        .sum::<usize>();
    assert!(parse_xlsx_fragment_capped(&bytes, cells).is_ok());
    assert_eq!(
        parse_xlsx_fragment_capped(&bytes, cells - 1).unwrap_err(),
        ParseError::LimitCells
    );
}

#[test]
fn parse_xlsx_refuses_hostile_and_foreign_containers() {
    let code = |name: &str| parse_xlsx(&fixture(name)).unwrap_err().code();
    assert_eq!(code("zip-bomb-size.xlsx"), "DOCS_PARSE_ZIP_BOMB");
    assert_eq!(code("zip-bomb-ratio.docx"), "DOCS_PARSE_ZIP_BOMB");
    assert_eq!(code("zip-traversal.docx"), "DOCS_PARSE_CORRUPT");
    assert_eq!(code("zip-plain.zip"), "DOCS_PARSE_CORRUPT");
    assert_eq!(code("docx-encrypted.docx"), "DOCS_PARSE_ENCRYPTED");
    assert_eq!(code("legacy.doc"), "DOCS_PARSE_CORRUPT");
    // A docx package is not a workbook.
    assert_eq!(
        parse_xlsx(b"not a zip at all, but long enough to read a tail ........").unwrap_err(),
        ParseError::Corrupt
    );
}

// ---- csv ------------------------------------------------------------------

#[test]
fn parse_csv_rows_are_records_with_header_values() {
    let n = csv("comma.csv");
    assert!(n.ir.meta.encoding.is_some());
    let table = &n.ir.blocks[0];
    assert_eq!(table.kind, BlockKind::SheetTable);
    assert_eq!(table.anchor.fragment(), "#A1:C3");
    let r2 = &n.ir.blocks[1];
    assert_eq!(r2.kind, BlockKind::Kv);
    assert_eq!(r2.text, "编号: T-1\n任务: 整理 OKR\n负责人: 周若溪");
    assert_eq!(r2.anchor.fragment(), "#R2");
    // Doubled quotes inside a quoted field.
    assert_eq!(
        n.ir.blocks[2].text,
        "编号: T-2\n任务: 开通 \"北辰\" 环境\n负责人: 陈子墨"
    );
    assert_eq!(n.ir.blocks[2].anchor.fragment(), "#R3");
    assert_eq!(
        n.ir.blocks
            .iter()
            .map(|b| b.id.clone())
            .collect::<BTreeSet<_>>()
            .len(),
        3
    );
}

#[test]
fn parse_csv_dialects_are_sniffed() {
    assert_eq!(sniff_delimiter("id;name;note\n1;a;x\n2;b;y\n"), ';');
    assert_eq!(sniff_delimiter("id\tname\n1\ta,b\n2\tc,d\n"), '\t');
    assert_eq!(sniff_delimiter("a,b,c\n1,2,3\n"), ',');
    assert_eq!(sniff_delimiter("just one column\nnext\n"), ',');
    let n = csv("semicolon.csv");
    assert_eq!(n.ir.blocks[1].text, "id: 1\nname: a\nnote: x");
    // The comma inside a tab-separated value stays in the value.
    let n = csv("tab.csv");
    assert_eq!(n.ir.blocks[1].text, "id: 1\nname: a,b");
}

#[test]
fn parse_csv_quoted_newline_is_one_row_and_blank_lines_count() {
    let n = csv("quoted-multiline.csv");
    let kv: Vec<_> =
        n.ir.blocks
            .iter()
            .filter(|b| b.kind == BlockKind::Kv)
            .collect();
    assert_eq!(kv.len(), 2);
    assert_eq!(kv[0].text, "id: 1\nnote: line one\nline two");
    assert_eq!(kv[0].anchor.fragment(), "#R2");
    assert_eq!(kv[1].anchor.fragment(), "#R3");

    // A blank line is a row: it keeps the numbering of what follows.
    let n = csv("blank-lines.csv");
    let rows: Vec<String> =
        n.ir.blocks
            .iter()
            .filter(|b| b.kind == BlockKind::Kv)
            .map(|b| b.anchor.fragment())
            .collect();
    assert_eq!(rows, vec!["#R2", "#R4"]);
}

#[test]
fn parse_csv_without_header_uses_column_letters() {
    let n = csv("no-header.csv");
    assert!(n.ir.blocks[0].flags.contains(&BlockFlag::HeaderInferred));
    assert_eq!(n.ir.blocks[0].table.as_ref().unwrap().header_rows, 0);
    assert_eq!(n.ir.blocks[1].text, "A: 1\nB: 2\nC: 3");
    assert_eq!(n.ir.blocks[1].anchor.fragment(), "#R1");
}

#[test]
fn parse_csv_encodings_empty_and_caps() {
    let n = csv("utf16-bom.csv");
    assert_eq!(n.ir.blocks[1].text, "k: 1\nv: 2");
    let e = csv("empty.csv");
    assert!(e.ir.blocks.is_empty());
    assert!(e.ir.warnings.iter().any(|w| w.code == "DOCS_PARSE_EMPTY"));
    // GB18030 stays unsupported (no decoder is admitted).
    assert_eq!(
        parse_csv(&fixture("gb18030.csv")).unwrap_err().code(),
        "DOCS_PARSE_ENCODING"
    );
    let bytes = fixture("comma.csv");
    assert_eq!(
        parse_csv_fragment_capped(&bytes, 5).unwrap_err(),
        ParseError::LimitCells
    );
    assert!(parse_csv_fragment_capped(&bytes, 9).is_ok());
    // A record wider than XFD is refused instead of overflowing A1 ranges.
    let wide = vec!["x"; 16_385].join(",");
    assert_eq!(
        parse_csv(wide.as_bytes()).unwrap_err(),
        ParseError::LimitCells
    );
}

#[test]
fn parse_csv_row_limit_keeps_the_table_block() {
    // More rows than the kv budget: later rows only live in the sheet_table.
    let mut text = String::from("a,b\n");
    for i in 0..205_000 {
        text.push_str(&format!("{i},x\n"));
    }
    let n = parse_csv(text.as_bytes()).unwrap();
    assert!(n.ir.blocks.len() <= oo_core::docir::MAX_BLOCKS);
    assert_eq!(n.ir.blocks[0].kind, BlockKind::SheetTable);
    assert!(
        n.ir.warnings
            .iter()
            .any(|w| w.code == "DOCS_PARSE_ROWS_TRUNCATED")
    );
    assert!(
        n.ir.warnings
            .iter()
            .any(|w| w.code == "DOCS_PARSE_TABLE_TRUNCATED")
    );
    assert_eq!(n.ir.blocks[0].table.as_ref().unwrap().rows, 205_001);
}

// ---- sniff + zipguard on files ----------------------------------------------

fn sniff_file(name: &str) -> (Format, Verdict, bool) {
    let bytes = fixture(name);
    let ext = oo_docs::ingest::sniff::extension(name);
    let s = sniff_reader(&mut Cursor::new(&bytes), bytes.len() as u64, &ext).unwrap();
    (s.format, s.verdict, s.has_macros)
}

#[test]
fn sniff_fixture_files() {
    use Verdict::*;
    assert_eq!(
        sniff_file("xlsx-merged-regions.xlsx"),
        (Format::Xlsx, Parseable, false)
    );
    assert_eq!(
        sniff_file("xlsx-macros.xlsx"),
        (Format::Xlsx, Parseable, true)
    );
    // Content wins over the extension.
    assert_eq!(
        sniff_file("zip-bomb-ratio.docx").1,
        Unsupported("DOCS_PARSE_ZIP_BOMB")
    );
    assert_eq!(
        sniff_file("zip-bomb-size.xlsx").1,
        Unsupported("DOCS_PARSE_ZIP_BOMB")
    );
    assert_eq!(
        sniff_file("zip-traversal.docx").1,
        Unsupported("DOCS_PARSE_CORRUPT")
    );
    assert_eq!(sniff_file("zip-plain.zip").0, Format::Zip);
    assert_eq!(
        sniff_file("docx-encrypted.docx"),
        (Format::LegacyOffice, Encrypted, false)
    );
    assert_eq!(
        sniff_file("legacy.doc").1,
        Unsupported("DOCS_PARSE_LEGACY_OFFICE")
    );
    assert_eq!(
        sniff_file("pdf-encrypted.pdf"),
        (Format::Pdf, Encrypted, false)
    );
    assert_eq!(sniff_file("pdf-plain.pdf"), (Format::Pdf, Parseable, false));
    assert_eq!(
        sniff_file("gb18030.txt").1,
        Unsupported("DOCS_PARSE_ENCODING")
    );
    assert_eq!(sniff_file("comma.csv"), (Format::Csv, Parseable, false));
    assert_eq!(sniff_file("empty.csv").1, Parseable);
}

#[test]
fn zipguard_reports_the_package() {
    let r = zipguard::check_bytes(&fixture("xlsx-merged-regions.xlsx")).unwrap();
    assert_eq!(r.package, zipguard::Package::Xlsx);
    assert!(r.max_sheet_xml > 0);
    // zip64 sizes are read from the extra field.
    let big = zipguard::check_bytes(&fixture("zip-bomb-size.xlsx")).unwrap_err();
    assert_eq!(big.code(), "DOCS_PARSE_ZIP_BOMB");
}

// ---- golden labels -----------------------------------------------------------

#[derive(Debug)]
enum Want {
    Row(u32),
    Range(String, (u32, u32, u32, u32)),
}

fn parse_frag(frag: &str) -> Option<Want> {
    let f = frag.strip_prefix('#')?;
    if let Some(row) = f.strip_prefix('R') {
        return Some(Want::Row(row.parse().ok()?));
    }
    let f = f.strip_prefix('\'')?;
    let (sheet, rest) = f.split_once("'!")?;
    let ((c0, r0), (c1, r1)) = a1_parse(rest)?;
    Some(Want::Range(sheet.replace("''", "'"), (c0, r0, c1, r1)))
}

fn overlaps(b: &Block, want: &Want) -> bool {
    let (sheet, range) = cells_range(b);
    let Some(((c0, r0), (c1, r1))) = a1_parse(range) else {
        return false;
    };
    match want {
        Want::Row(r) => sheet.is_none() && r0 <= *r && *r <= r1,
        Want::Range(s, (wc0, wr0, wc1, wr1)) => {
            sheet == Some(s.as_str()) && c0 <= *wc1 && *wc0 <= c1 && r0 <= *wr1 && *wr0 <= r1
        }
    }
}

fn exact(b: &Block, want: &Want) -> bool {
    let (sheet, range) = cells_range(b);
    let Some(((c0, r0), (c1, r1))) = a1_parse(range) else {
        return false;
    };
    match want {
        Want::Row(r) => sheet.is_none() && b.kind == BlockKind::Kv && r0 == *r && r1 == *r,
        Want::Range(s, (wc0, wr0, wc1, wr1)) => {
            sheet == Some(s.as_str())
                && b.kind == BlockKind::Kv
                && (c0, r0, c1, r1) == (*wc0, *wr0, *wc1, *wr1)
        }
    }
}

#[test]
fn parse_golden_tabular_label_anchors_land_in_blocks() {
    let golden = root().join("golden");
    let mut anchors: BTreeSet<(String, String)> = BTreeSet::new();
    for entry in fs::read_dir(golden.join("labels")).unwrap() {
        let path = entry.unwrap().path();
        if path.extension().is_none_or(|e| e != "jsonl") {
            continue;
        }
        for line in fs::read_to_string(&path).unwrap().lines() {
            let v: serde_json::Value = serde_json::from_str(line).unwrap();
            for a in v["anchors"].as_array().into_iter().flatten() {
                let file = a["file"].as_str().unwrap();
                if file.ends_with(".xlsx") || file.ends_with(".csv") {
                    anchors.insert((file.to_owned(), a["frag"].as_str().unwrap().to_owned()));
                }
            }
        }
    }
    assert!(!anchors.is_empty());
    let mut parsed: std::collections::BTreeMap<String, Normalized> = Default::default();
    let (mut total, mut covered, mut row_level) = (0, 0, 0);
    let (mut xlsx_total, mut csv_total) = (0, 0);
    let mut missing = Vec::new();
    for (file, frag) in &anchors {
        let n = parsed.entry(file.clone()).or_insert_with(|| {
            let bytes = fs::read(golden.join(file)).unwrap();
            let n = if file.ends_with(".xlsx") {
                parse_xlsx(&bytes).unwrap()
            } else {
                parse_csv(&bytes).unwrap()
            };
            // Every produced IR re-validates through the normalizer.
            assert!(roundtrips(&n));
            n
        });
        let want = parse_frag(frag).unwrap_or_else(|| panic!("unparsed fragment {frag}"));
        total += 1;
        if file.ends_with(".xlsx") {
            xlsx_total += 1;
        } else {
            csv_total += 1;
        }
        if n.ir.blocks.iter().any(|b| overlaps(b, &want)) {
            covered += 1;
        } else {
            missing.push((file.clone(), frag.clone()));
        }
        if n.ir.blocks.iter().any(|b| exact(b, &want)) {
            row_level += 1;
        }
    }
    eprintln!(
        "golden tabular anchors: total={total} (xlsx={xlsx_total}, csv={csv_total}) \
         in_a_block={covered} exact_row_blocks={row_level} files={}",
        parsed.len()
    );
    assert!(missing.is_empty(), "{missing:?}");
    assert_eq!(parsed.len(), 7, "3 csv + 4 xlsx golden files");
    // Header rows (row 1) are covered by the sheet_table block only.
    assert!(row_level < total);
}

fn roundtrips(n: &Normalized) -> bool {
    // The canonical bytes decode back to the same, valid IR.
    let back: oo_core::docir::DocIr = serde_json::from_str(&n.canonical).unwrap();
    back == n.ir && oo_core::docir::validate(&back).is_empty()
}
